import{_ as e,o as a,c as i,a2 as d}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Telegram REST API","description":"","frontmatter":{},"headers":[],"relativePath":"api-documentation/v1/utilities-api/telegram.md","filePath":"api-documentation/v1/utilities-api/telegram.md"}'),s={name:"api-documentation/v1/utilities-api/telegram.md"};function o(r,t,n,l,c,p){return a(),i("div",null,[...t[0]||(t[0]=[d(`<h1 id="telegram-rest-api" tabindex="-1">Telegram REST API <a class="header-anchor" href="#telegram-rest-api" aria-label="Permalink to &quot;Telegram REST API&quot;">​</a></h1><p>The Telegram namespace exposes configuration, lifecycle, user, notification, statistics, and preference resources. Most calls accept the Tradeboard key in <code>X-API-KEY</code>, the <code>apikey</code> query parameter for GET, or the JSON body for POST.</p><h2 id="endpoint-inventory" tabindex="-1">Endpoint Inventory <a class="header-anchor" href="#endpoint-inventory" aria-label="Permalink to &quot;Endpoint Inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Authentication</th><th>Current behavior</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/v1/telegram/config</code></td><td>API key</td><td>Returns configuration with the bot token masked</td></tr><tr><td>POST</td><td><code>/api/v1/telegram/config</code></td><td>API key</td><td>Updates accepted configuration fields</td></tr><tr><td>POST</td><td><code>/api/v1/telegram/start</code></td><td>API key</td><td>Initializes polling or webhook mode from stored config</td></tr><tr><td>POST</td><td><code>/api/v1/telegram/stop</code></td><td>API key</td><td>Stops the bot service</td></tr><tr><td>POST</td><td><code>/api/v1/telegram/webhook</code></td><td>Telegram secret header</td><td>Validates and acknowledges updates; dispatch is not implemented</td></tr><tr><td>GET</td><td><code>/api/v1/telegram/users</code></td><td>API key</td><td>Lists linked users, optionally filtered</td></tr><tr><td>POST</td><td><code>/api/v1/telegram/broadcast</code></td><td>API key</td><td>Validates request but currently reports zero deliveries</td></tr><tr><td>POST</td><td><code>/api/v1/telegram/notify</code></td><td>API key</td><td>Queues or synchronously sends one linked user&#39;s message</td></tr><tr><td>GET</td><td><code>/api/v1/telegram/stats</code></td><td>API key</td><td>Returns command statistics for 1 to 365 days</td></tr><tr><td>GET</td><td><code>/api/v1/telegram/preferences</code></td><td>API key</td><td>Reads preferences for a <code>telegram_id</code></td></tr><tr><td>POST</td><td><code>/api/v1/telegram/preferences</code></td><td>API key</td><td>Updates supported preferences for a <code>telegram_id</code></td></tr></tbody></table><h2 id="direct-notification" tabindex="-1">Direct Notification <a class="header-anchor" href="#direct-notification" aria-label="Permalink to &quot;Direct Notification&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://127.0.0.1:5000/api/v1/telegram/notify&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;apikey&quot;: &quot;&lt;your_app_apikey&gt;&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;username&quot;: &quot;tradeboard-user&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;message&quot;: &quot;Strategy alert&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;wait_for_delivery&quot;: false</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p><code>username</code> must already be linked to a Telegram ID. With the default asynchronous path, HTTP 200 means queued, not confirmed delivered. <code>wait_for_delivery: true</code> waits for an immediate attempt; a failed attempt is queued for retry and still returns a queued success message.</p><h2 id="webhook-authentication" tabindex="-1">Webhook Authentication <a class="header-anchor" href="#webhook-authentication" aria-label="Permalink to &quot;Webhook Authentication&quot;">​</a></h2><p>Telegram sends <code>X-Telegram-Bot-Api-Secret-Token</code>. Tradeboard compares it with <code>TELEGRAM_WEBHOOK_SECRET</code>, or with a token-derived fallback when the explicit secret is absent. Missing and incorrect headers return 401 and 403 respectively. Structurally valid updates are acknowledged with an empty HTTP 200 response, but <code>process_webhook_update</code> is not implemented in this RESTX handler.</p><h2 id="automatic-alert-gate" tabindex="-1">Automatic Alert Gate <a class="header-anchor" href="#automatic-alert-gate" aria-label="Permalink to &quot;Automatic Alert Gate&quot;">​</a></h2><p>Order-event and Flow alerts check the persisted bot <code>is_active</code> state. Stopping the bot suppresses those automatic alerts. Explicit admin sends and <code>/telegram/notify</code> intentionally bypass that gate.</p><h2 id="rate-limits" tabindex="-1">Rate Limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate Limits&quot;">​</a></h2><p>Most Telegram resources use <code>TELEGRAM_RATE_LIMIT</code> (default <code>30 per minute</code>). Broadcast is independently limited to <code>5 per minute</code>.</p><p><strong>Back to</strong>: <a href="./../README">API documentation</a></p>`,14)])])}const k=e(s,[["render",o]]);export{u as __pageData,k as default};
